"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6448],{54518:e=>{e.exports=JSON.parse('{"functions":[{"name":"isFeasible","desc":"True if this output can be granted to `player` right now (template exists,\\narmor kind exists and is not already owned at full pool). Checked before\\nmaterials are consumed, so a redundant or misconfigured craft never costs the\\nplayer anything.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"output","desc":"","lua_type":"Output"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":58,"path":"src/ServerStorage/SharedModules/CraftOutputDispatcher.luau"}},{"name":"grant","desc":"Grant the output to the player. Returns true on success. Assumes\\n`isFeasible` already passed; a false here is a defensive last resort.","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"output","desc":"","lua_type":"Output"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":78,"path":"src/ServerStorage/SharedModules/CraftOutputDispatcher.luau"}}],"properties":[],"types":[],"name":"CraftOutputDispatcher","desc":"Server-side grant logic for a recipe\'s `Output`, dispatched on `Output.Kind`\\nso each output type is isolated (mirrors TechEffectsDispatcher). `isFeasible`\\nis checked by WorkbenchService BEFORE consuming materials, so a misconfigured\\nrecipe never costs the player materials; `grant` performs the actual award.\\n\\t- Weapon    \u2192 clone a Tool from ServerStorage/<WEAPON_TEMPLATES_FOLDER> to Backpack\\n\\t- Armor     \u2192 ArmorManager.Grant(player, ArmorKind)\\n\\t- Placeable \u2192 clone ReplicatedStorage/PlaceableTools/<Name> to Backpack\\n\\t- Ammo      \u2192 AmmoManager.AddAmmo(player, AmmoType, Amount)","realm":["Server"],"source":{"line":15,"path":"src/ServerStorage/SharedModules/CraftOutputDispatcher.luau"}}')}}]);